import {connectionEndpoints} from './connections.js';
import {groupAncestors,groupMembers} from './structure.js';
import {connectedObjects} from './articulated-joints.js';
// Editor limits project endpoint distance onto the rope's maximum-length sphere.
// Rigid groups and articulated editing assemblies translate together.
export function enforceEditorRopes(project,{preferredIds=[],iterations=64}={}){const objects=new Map(project.objects.map(o=>[o.id,o])),preferred=new Set(preferredIds),ropes=(project.connections||[]).filter(c=>c.kind==='rope'),changed=new Set(),assemblies=new Map();const assembly=(id,group)=>{const key=group||id;if(assemblies.has(key))return assemblies.get(key);let ids=new Set(group?groupMembers(project,group):[id]);for(let count=0;count<project.objects.length;count++){const before=ids.size;ids=new Set(connectedObjects(project,[...ids]));for(const member of [...ids]){const o=objects.get(member),root=o&&groupAncestors(project,o)[0];if(root)for(const n of groupMembers(project,root.id))ids.add(n);}if(ids.size===before)break;}const out=[...ids];assemblies.set(key,out);return out;};const shift=(ids,delta)=>{for(const id of ids){const o=objects.get(id);o.position=o.position.map((v,i)=>v+delta[i]);changed.add(id);}for(const c of project.connections||[])if(c.kind==='hinge'&&ids.includes(c.a))c.worldPoint=c.worldPoint.map((v,i)=>v+delta[i]);};for(let pass=0;pass<iterations;pass++){let max=0;for(const c of ropes){const [a,b]=connectionEndpoints(c,objects),d=b.map((v,i)=>v-a[i]),distance=Math.hypot(...d),excess=distance-c.length;if(excess<=1e-7)continue;max=Math.max(max,excess);const idsA=assembly(c.a,c.groupA),idsB=c.b?assembly(c.b,c.groupB):[],overlap=c.b&&idsA.some(id=>idsB.includes(id));if(overlap)throw Error('묶음 안 줄의 최대 길이가 연결점 사이 거리보다 짧습니다.');const moveB=c.b&&(!idsA.some(id=>preferred.has(id))||idsB.some(id=>preferred.has(id))),delta=d.map(v=>v/distance*excess*(moveB?-1:1));shift(moveB?idsB:idsA,delta);}if(max<=1e-7)return [...changed];}if(ropes.some(c=>{const [a,b]=connectionEndpoints(c,objects);return Math.hypot(...a.map((v,i)=>v-b[i]))>c.length+1e-5;}))throw Error('여러 줄의 최대 길이를 동시에 맞출 수 없습니다. 고정점이나 길이를 조절하세요.');return [...changed];}
